:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
  --focus: #f5c542;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.app {
  background: var(--card);
  padding: 2rem;
  border-radius: 1rem;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  width: min(90vw, 400px);
  text-align: center;
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 1.5rem;
  color: var(--primary);
  letter-spacing: 0.05em;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

label {
  text-align: left;
  font-size: 0.9rem;
  opacity: 0.9;
}

input {
  padding: 0.6rem;
  border-radius: 0.5rem;
  border: 2px solid var(--accent);
  background: var(--bg);
  color: var(--text);
  font-size: 1rem;
  width: 100%;
}

input:focus {
  outline: 2px solid var(--focus);
  border-color: var(--focus);
}

button {
  padding: 0.75rem 1rem;
  border: none;
  border-radius: 0.5rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button.primary {
  background: var(--primary);
  color: #fff;
}

button.primary:hover { background: #c73650; }
button.primary:active { transform: scale(0.97); }

button.secondary {
  background: var(--accent);
  color: var(--text);
}

button.secondary:hover { background: #1a4a7a; }
button.secondary:active { transform: scale(0.97); }

button:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.display {
  background: var(--bg);
  border-radius: 0.75rem;
  padding: 1rem;
}

#phase {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0 0 0.25rem;
  color: var(--primary);
}

#round {
  font-size: 1rem;
  margin: 0 0 0.5rem;
  opacity: 0.8;
}

#time {
  font-size: 2.5rem;
  font-weight: 700;
  margin: 0;
  font-variant-numeric: tabular-nums;
}

#message {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--focus);
  margin: 0.5rem 0 0;
}

[hidden] { display: none !important; }

@media (max-width: 400px) {
  .app { padding: 1.25rem; }
  h1 { font-size: 1.25rem; }
  #time { font-size: 2rem; }
}

const workInput = document.getElementById('work');
const restInput = document.getElementById('rest');
const roundsInput = document.getElementById('rounds');
const startBtn = document.getElementById('start');
const resetBtn = document.getElementById('reset');
const phaseEl = document.getElementById('phase');
const roundEl = document.getElementById('round');
const timeEl = document.getElementById('time');
const messageEl = document.getElementById('message');

let timer = null;
let currentRound = 0;
let totalRounds = 0;
let workSeconds = 0;
let restSeconds = 0;
let remaining = 0;
let phase = 'idle'; // idle, work, rest, done

function formatTime(sec) {
  const m = Math.floor(sec / 60).toString().padStart(2, '0');
  const s = (sec % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateDisplay() {
  timeEl.textContent = formatTime(remaining);
  roundEl.textContent = `Round ${currentRound} / ${totalRounds}`;
  if (phase === 'work') phaseEl.textContent = 'Work';
  else if (phase === 'rest') phaseEl.textContent = 'Rest';
  else if (phase === 'done') phaseEl.textContent = 'Done';
  else phaseEl.textContent = 'Ready';
}

function tick() {
  remaining--;
  if (remaining <= 0) {
    if (phase === 'work') {
      if (currentRound < totalRounds) {
        phase = 'rest';
        remaining = restSeconds;
      } else {
        finish();
        return;
      }
    } else if (phase === 'rest') {
      currentRound++;
      if (currentRound > totalRounds) {
        finish();
        return;
      }
      phase = 'work';
      remaining = workSeconds;
    }
  }
  updateDisplay();
}

function finish() {
  clearInterval(timer);
  timer = null;
  phase = 'done';
  remaining = 0;
  updateDisplay();
  messageEl.hidden = false;
  startBtn.disabled = false;
}

function start() {
  if (timer) return;
  workSeconds = Math.max(1, parseInt(workInput.value) || 1);
  restSeconds = Math.max(1, parseInt(restInput.value) || 1);
  totalRounds = Math.max(1, parseInt(roundsInput.value) || 1);
  currentRound = 1;
  phase = 'work';
  remaining = workSeconds;
  messageEl.hidden = true;
  startBtn.disabled = true;
  updateDisplay();
  timer = setInterval(tick, 1000);
}

function reset() {
  clearInterval(timer);
  timer = null;
  phase = 'idle';
  currentRound = 0;
  totalRounds = 0;
  remaining = 0;
  messageEl.hidden = true;
  startBtn.disabled = false;
  updateDisplay();
}

startBtn.addEventListener('click', start);
resetBtn.addEventListener('click', reset);

// Initialize display
reset();
